/*getShoppintCartSelectSql1*/ SELECT
ROWNUM NO, -- 00 Z.IMGFILE_NAME, -- 01 Z.IMGFILE_DIR, -- 02 Z.BUYER_ITEM_NO, -- 03 Z.DESCRIPTION_LOC, -- 04 Z.SPECIFICATION, -- 05 Z.ORIGIN_NAME, -- 06 Z.MAKER_NAME, -- 07 Z.UNIT_MEASURE, -- 08 Z.TARGET_PRICE, -- 09 Z.CATEGORY_NO, -- 10 DECODE(NVL(Z.AGENT,'MULTI'),'MULTI','복수협력사입니다','+','복수협력사입니다', DECODE((SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE COM_CODE = #{st_buyer} ) ,'N','코리아e플랫폼(주)', Z.AGENT)) AGENT, -- 11 Z.CART_QTY, -- 12 Z.TOT_SUM, -- 13 Z.STDCATEG_ID, -- 14 Z.CONTRACT_NO, -- 15 Z.CONTRACT_SEQ, -- 16 Z.BYIT_COMORG_CODE, -- 17 Z.REF_PR_NO, -- 18 Z.AGENT_CODE, -- 19 Z.BDGT_FLAG, -- 20 Z.ACCOUNT_TYPE, -- 21 Z.FIXED_PRICE_FLAG, -- 22 DECODE((SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE com_code = #{st_buyer} ) ,'N','KRKORE0001', Z.AGENT_CODE) AGENT3, --23 Z.ACCOUNT_NAME, --24 Z.BUDGET_DEPT_CODE, --25 Z.BUDGET_DEPT_NAME, --26 Z.OVER_SHORT_FLAG, --27 Z.HS_NO, --28 Z.PRODUCT_CLOSE_FLAG, --29 Z.PROCESS_TYPE, --30 Z.STOCK_ITEM_FLAG --31 , Z.HI_DEPT_CODE --32 홍익대학교 추가 , Z.HI_DEPT_NAME --33 홍익대학교 추가 , Z.REF_PR_NAME --34 홍익대학교 추가 , Z.IMAGE_KEY --35.첨부파일추가 , (SELECT TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'K005' AND COD.FLAG = 'Y' AND COD.CODE = Z.BUYER_ITEM_NO AND ROWNUM = 1) MG_CODE --36.명함,사원증구분 , Z.BYIT_BDGT_FLAG MG_NOTE --37.COWAY 예산사용여부 , Z.CMS_CATEG_ID --38.표준카테고리코드 , Z.CATE_APPR --39.카테고리별결재담당자 , Z.SEQ CART_SEQ , Z.ITEM_STATUS_FLAG --41 삭제건 표기 , Z.MIN_ORDER_QTY , Z.URCT2_YN FROM (SELECT ROWNUM NUM, Y.IMGFILE_NAME, Y.IMGFILE_DIR, Y.BUYER_ITEM_NO, Y.DESCRIPTION_LOC, Y.SPECIFICATION, Y.ORIGIN_NAME, Y.MAKER_NAME, Y.UNIT_MEASURE, Y.TARGET_PRICE, Y.CATEGORY_NO, Y.AGENT, Y.CART_QTY, Y.TOT_SUM, Y.STDCATEG_ID, Y.CONTRACT_NO, Y.CONTRACT_SEQ, Y.BYIT_COMORG_CODE, Y.REF_PR_NO, Y.AGENT_CODE, Y.BDGT_FLAG, NVL(Y.ACCOUNT_TYPE, GETCOWAYBGACTIFNO('BGACT' ,Y.BUYER, Y.USER_ID,Y.BUDGET_DEPT_CODE)) ACCOUNT_TYPE, Y.FIXED_PRICE_FLAG, GETCOWAYBGACT_NMIFNO('BGACT',Y.BUYER, Y.USER_ID, NVL(Y.ACCOUNT_TYPE, GETCOWAYBGACTIFNO('BGACT' ,Y.BUYER, Y.USER_ID,Y.BUDGET_DEPT_CODE))) ACCOUNT_NAME, Y.BUDGET_DEPT_CODE, GETCOWAYBGACT_NMIFNO('BGORG',Y.BUYER, Y.USER_ID, Y.BUDGET_DEPT_CODE) BUDGET_DEPT_NAME, Y.OVER_SHORT_FLAG, Y.HS_NO, Y.PRODUCT_CLOSE_FLAG, Y.PROCESS_TYPE , Y.STOCK_ITEM_FLAG , Y.HI_DEPT_CODE , Y.HI_DEPT_NAME , Y.REF_PR_NAME , Y.IMAGE_KEY , Y.BYIT_BDGT_FLAG , Y.CMS_CATEG_ID , Y.CATE_APPR , Y.SEQ , Y.ITEM_STATUS_FLAG , Y.MIN_ORDER_QTY , Y.URCT2_YN FROM ( SELECT DECODE(TRIM(B.IMGFILE_NAME), NULL, (SELECT IMG_NAME FROM CMSIMGES WHERE IMG_NO=D.IMG_NO),B.IMGFILE_NAME) AS IMGFILE_NAME, DECODE(TRIM(B.IMGFILE_DIR), NULL, (SELECT IMG_DIR FROM CMSIMGES WHERE IMG_NO=D.IMG_NO),B.IMGFILE_DIR) AS IMGFILE_DIR, C.BUYER_ITEM_NO BUYER_ITEM_NO, C.DESCRIPTION DESCRIPTION_LOC, C.SPECIFICATION, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = C.ORIGIN_CODE) ORIGIN_NAME, C.MAKER_NAME, C.UNIT_MEASURE, DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.UNIT_PRICE,0),NVL(C.TARGET_PRICE,0)) TARGET_PRICE, B.CATEGORY_NO, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE C.AGENT = COM_CODE) AS AGENT, DECODE(A.CART_QTY,'0','1',NVL(A.CART_QTY,1)) CART_QTY, (DECODE(A.CART_QTY,'0','1',NVL(A.CART_QTY,1)) * DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.UNIT_PRICE,0),NVL(C.TARGET_PRICE,0)) ) TOT_SUM, B.STDCATEG_ID, C.CONTRACT_NO, C.CONTRACT_SEQ, A.BYIT_COMORG_CODE, A.REF_PR_NO, C.AGENT AS AGENT_CODE, (SELECT Z.FLAG FROM ICOMCOD2 Z WHERE Z.TYPE = 'Z014' AND Z.COMPANY_CODE = A.BUYER AND Z.CODE = B.ACCOUNT_TYPE) BDGT_FLAG, B.FIXED_PRICE_FLAG FIXED_PRICE_FLAG, NVL(A.BUDGET_DEPT, GETCOWAYBGACTIFNO('BGORG' ,A.BUYER, A.USER_ID,'')) BUDGET_DEPT_CODE, A.ACCOUNT_TYPE , NVL(TRIM(B.OVER_SHORT_FLAG),'N') AS OVER_SHORT_FLAG, TRIM(B.HS_NO) AS HS_NO, B.PRODUCT_CLOSE_FLAG AS PRODUCT_CLOSE_FLAG ,C.PROCESS_TYPE ,DECODE( C.PROCESS_TYPE,'1' , (SELECT DECODE(COUNT(*),0,'N','Y') FROM ICOMBYIT IT, ICOMCOD1 D, WMSSTCK W WHERE D.TYPE ='HUB' AND D.CODE = C.AGENT AND IT.BUYER_ITEM_NO = B.CMS_CATLG_ID AND IT.PRODUCT_CLOSE_FLAG ='N' AND W.STDCATLG_ID = IT.BUYER_ITEM_NO AND W.WAREHOUSE_CODE = D.TEXT1 ) , 'Y' ) AS STOCK_ITEM_FLAG , A.HI_DEPT_CODE , (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND CODE = A.HI_DEPT_CODE AND TYPE = 'U001' AND FLAG = 'Y') AS HI_DEPT_NAME , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND CODE = A.REF_PR_NO AND TYPE = 'M014' AND FLAG = 'Y') AS REF_PR_NAME , A.IMAGE_KEY , A.BUYER, A.USER_ID, (CASE WHEN E.BUDGET_FLAG ='Y' AND B.ACCOUNT_TYPE = 'M' THEN 'Y' ELSE 'N' END) AS BYIT_BDGT_FLAG , B.CMS_CATEG_ID , (SELECT COUNT(*) FROM ICOMCOD3 CT WHERE CT.BUYER = A.BUYER AND CT.CODE1 = B.CATEGORY_NO AND CT.TYPE = 'CATE' AND CT.FLAG = 'Y') AS CATE_APPR , A.SEQ , DECODE(B.STATUS||C.STATUS,'CC','거래','CR','거래','RC','거래','RR','거래','DC','삭제','DR','삭제','DD','삭제','CD','삭제','RD','삭제','거래') AS ITEM_STATUS_FLAG , NVL(C.MIN_ORDER_QTY, 1) AS MIN_ORDER_QTY , CASE WHEN B.CATEGORY_NO IN ( SELECT DISTINCT STD_CATEG_ID FROM ( SELECT STD_CATEG_ID FROM ICOMBYCA A, ICOMCOD3 B WHERE A.COM_CODE=B.BUYER AND A.COM_CODE = ( SELECT DISTINCT BYCA_COMORG_CODE FROM ICOMCMPY WHERE (COM_CODE = #{st_buyer} OR BYCA_COMORG_CODE = #{st_buyer}) ) AND A.COM_CODE = B.TEXT1 AND B.TYPE = 'URCT2' AND B.CODE1 = #{st_user_id} AND B.FLAG = 'Y' AND SUBSTR(A.CATEG_SYS_CODE,1,8) = B.TEXT2 UNION ALL SELECT DISTINCT STD_CATEG_ID FROM ICOMBYCA A WHERE A.COM_CODE = ( SELECT DISTINCT BYCA_COMORG_CODE FROM ICOMCMPY WHERE (COM_CODE = #{st_buyer} OR BYCA_COMORG_CODE = #{st_buyer}) ) AND NOT EXISTS ( SELECT 1 FROM ICOMCOD3 B WHERE B.BUYER = A.COM_CODE AND B.TEXT1 = A.COM_CODE AND B.TEXT2 = SUBSTR(A.CATEG_SYS_CODE,1,8) AND B.TYPE = 'URCT2' AND B.FLAG = 'Y' ) ) ) THEN 'Y' ELSE 'N' END AS URCT2_YN FROM ICOMCART A, ICOMBYIT B, ICOMCQDT C, CMSCATLG D, ICOMCMPY E WHERE B.BUYER = C.BUYER AND A.BUYER = E.COM_CODE AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND A.BUYER = #{st_buyer} AND A.BYIT_COMORG_CODE = B.BUYER AND A.USER_ID = #{st_user_id} AND B.CMS_CATLG_ID = D.CMS_CATLG_ID(+) AND D.STD_FLAG(+)='Y' AND A.USE_FLAG = 'C' AND B.PRODUCT_CLOSE_FLAG IN ('N','Y')
AND A.VERIF_NUM = #{st_verif_num}
ORDER BY A.CREATE_DATE, A.SEQ, A.BUYER_ITEM_NO
ORDER BY A.BUYER_ITEM_NO
ORDER BY A.REF_PR_NO, A.BUYER_ITEM_NO
) Y ) Z

