SELECT NUM NO, Z.IMGFILE_NAME, Z.IMGFILE_DIR, Z.BUYER_ITEM_NO, Z.DESCRIPTION_LOC, Z.SPECIFICATION, Z.ORIGIN_NAME, Z.MAKER_NAME, Z.UNIT_MEASURE, Z.TARGET_PRICE, Z.CATEGORY_NO, DECODE(NVL(Z.AGENT,'MULTI'),'MULTI','복수협력사입니다','+','복수협력사입니다', DECODE((SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE COM_CODE = #{st_buyer} ),'N','코리아e플랫폼(주)', Z.AGENT)) AGENT, Z.CART_QTY, Z.TOT_SUM, Z.STDCATEG_ID, Z.CONTRACT_NO, Z.CONTRACT_SEQ, Z.BYIT_COMORG_CODE, Z.REF_PR_NO, Z.AGENT_CODE, Z.BDGT_FLAG, Z.ACCOUNT_TYPE, Z.FIXED_PRICE_FLAG, DECODE(NVL(Z.AGENT,'MULTI'),'MULTI','MULTI_AGENT',DECODE((SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE COM_CODE = #{st_buyer} ),'N','KRKORE0001', Z.AGENT_CODE)) AGENT3, Z.ACCOUNT_NAME, --24 Z.BUDGET_DEPT_CODE, --25 Z.BUDGET_DEPT_NAME, --26 Z.OVER_SHORT_FLAG, --27 Z.HS_NO, --28 Z.PRODUCT_CLOSE_FLAG, --29 Z.PROCESS_TYPE, --30 Z.STOCK_ITEM_FLAG --31 , Z.HI_DEPT_CODE --32 홍익대학교 추가 , Z.HI_DEPT_NAME --33 홍익대학교 추가 , Z.REF_PR_NAME --34 홍익대학교 추가 , Z.MG_CODE --35 창성 계정 관리항목 추가 , Z.MG_NOTE --36 창성 계정 관리항목 추가 , Z.IMAGE_KEY , Z.BDGT_BAL_AMT , Z.SEQ , Z.URCT2_YN FROM (SELECT ROWNUM NUM, Y.IMGFILE_NAME, Y.IMGFILE_DIR, Y.BUYER_ITEM_NO, Y.DESCRIPTION_LOC, Y.SPECIFICATION, Y.ORIGIN_NAME, Y.MAKER_NAME, Y.UNIT_MEASURE, Y.TARGET_PRICE, Y.CATEGORY_NO, Y.AGENT, Y.CART_QTY, Y.TOT_SUM, Y.STDCATEG_ID, Y.CONTRACT_NO, Y.CONTRACT_SEQ, Y.BYIT_COMORG_CODE, Y.REF_PR_NO, Y.AGENT_CODE, Y.BDGT_FLAG, Y.ACCOUNT_TYPE, Y.FIXED_PRICE_FLAG, Y.ACCOUNT_NAME, Y.BUDGET_DEPT_CODE, Y.BUDGET_DEPT_NAME, Y.OVER_SHORT_FLAG, Y.HS_NO, Y.PRODUCT_CLOSE_FLAG, Y.PROCESS_TYPE , Y.STOCK_ITEM_FLAG , Y.HI_DEPT_CODE , Y.HI_DEPT_NAME , Y.REF_PR_NAME , Y.MG_CODE , Y.MG_NOTE , Y.IMAGE_KEY , Y.BDGT_BAL_AMT , Y.SEQ , Y.URCT2_YN FROM ( SELECT TRIM(DECODE(SUBSTR(B.STDCATLG_ID,0,1),'M', (SELECT IMG_NAME FROM XPROIMGE WHERE IMG_NO = (SELECT DISTINCT IMG_NO FROM ITEMMAST WHERE STDCATLG_ID = B.STDCATLG_ID) AND RANKING = 1),B.IMGFILE_NAME)) AS IMGFILE_NAME, TRIM(DECODE(SUBSTR(B.STDCATLG_ID,0,1),'M', (SELECT IMG_DIR FROM XPROIMGE WHERE IMG_NO = (SELECT DISTINCT IMG_NO FROM ITEMMAST WHERE STDCATLG_ID = B.STDCATLG_ID) AND RANKING = 1),B.IMGFILE_DIR)) AS IMGFILE_DIR, C.BUYER_ITEM_NO BUYER_ITEM_NO, C.DESCRIPTION DESCRIPTION_LOC, C.SPECIFICATION, (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = C.ORIGIN_CODE) ORIGIN_NAME, C.MAKER_NAME, C.UNIT_MEASURE, DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.UNIT_PRICE,0),NVL(C.TARGET_PRICE,0)) TARGET_PRICE, B.CATEGORY_NO, (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE C.AGENT = COM_CODE) AS AGENT, DECODE(A.CART_QTY,'0','1',NVL(A.CART_QTY,1)) CART_QTY, (DECODE(A.CART_QTY,'0','1',NVL(A.CART_QTY,1)) * DECODE(B.FIXED_PRICE_FLAG,'N',NVL(A.UNIT_PRICE,0),NVL(C.TARGET_PRICE,0)) ) TOT_SUM, B.STDCATEG_ID, C.CONTRACT_NO, C.CONTRACT_SEQ, A.BYIT_COMORG_CODE, A.REF_PR_NO, C.AGENT AS AGENT_CODE, (SELECT Z.FLAG FROM ICOMCOD2 Z WHERE Z.TYPE = 'Z014' AND Z.COMPANY_CODE = A.BUYER AND Z.CODE = B.ACCOUNT_TYPE) BDGT_FLAG, DECODE(A.ACCOUNT_TYPE,NULL,B.ACCOUNT_TYPE,A.ACCOUNT_TYPE) ACCOUNT_TYPE, B.FIXED_PRICE_FLAG FIXED_PRICE_FLAG, (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND TYPE = 'Z014' AND CODE = DECODE(A.ACCOUNT_TYPE,NULL,B.ACCOUNT_TYPE,A.ACCOUNT_TYPE)) AS ACCOUNT_NAME, (select DECODE(COUNT(*),0 , '', 1 , DECODE(DECODE(A.BUDGET_DEPT,NULL,#{st_user_dept} , A.BUDGET_DEPT ),MAX(F.CODE1),MAX(F.CODE1),''), MAX((SELECT F.CODE1 FROM ICOMCOD3 E , ICOMCOD3 F WHERE E.BUYER = A.BUYER AND E.CODE1 = #{st_user_dept} AND E.TYPE = 'DTOD' AND E.BUYER = F.BUYER AND E.CODE2 = F.CODE1 AND F.TYPE = 'DTOA' AND F.CODE1 = DECODE(A.BUDGET_DEPT,NULL,#{st_user_dept}, A.BUDGET_DEPT ) AND DECODE(F.FLAG,'Y',DECODE(#{st_user_dept},F.CODE1,'N','Y'),'N') = 'N' AND F.CODE2 = DECODE(A.ACCOUNT_TYPE,NULL,B.ACCOUNT_TYPE, A.ACCOUNT_TYPE ))) ) FROM ICOMCOD3 E , ICOMCOD3 F WHERE E.BUYER = A.BUYER AND E.CODE1 = #{st_user_dept} AND E.TYPE = 'DTOD' AND E.BUYER = F.BUYER AND E.CODE2 = F.CODE1 AND F.TYPE = 'DTOA' AND F.CODE2 = DECODE(A.ACCOUNT_TYPE,NULL,B.ACCOUNT_TYPE, A.ACCOUNT_TYPE ) ) BUDGET_DEPT_CODE, (select DECODE(COUNT(*),0 , '', 1 , DECODE(DECODE(A.BUDGET_DEPT,NULL,#{st_user_dept}, A.BUDGET_DEPT ),MAX(F.CODE1), MAX((SELECT TEXT1 FROM ICOMCOD2 T WHERE T.COMPANY_CODE = A.BUYER AND T.TYPE = 'C001' AND T.CODE = F.CODE1)) ,''), MAX((SELECT MAX((SELECT TEXT1 FROM ICOMCOD2 T WHERE T.COMPANY_CODE = A.BUYER AND T.TYPE = 'C001' AND T.CODE = F.CODE1)) FROM ICOMCOD3 E , ICOMCOD3 F WHERE E.BUYER = A.BUYER AND E.CODE1 = #{st_user_dept} AND E.TYPE = 'DTOD' AND E.BUYER = F.BUYER AND E.CODE2 = F.CODE1 AND F.TYPE = 'DTOA' AND F.CODE1 = DECODE(A.BUDGET_DEPT,NULL,#{st_user_dept}, A.BUDGET_DEPT ) AND DECODE(F.FLAG,'Y',DECODE(#{st_user_dept},F.CODE1,'N','Y'),'N') = 'N' AND F.CODE2 = DECODE(A.ACCOUNT_TYPE,NULL,B.ACCOUNT_TYPE, A.ACCOUNT_TYPE ))) ) FROM ICOMCOD3 E , ICOMCOD3 F WHERE E.BUYER = A.BUYER AND E.CODE1 = #{st_user_dept} AND E.TYPE = 'DTOD' AND E.BUYER = F.BUYER AND E.CODE2 = F.CODE1 AND F.TYPE = 'DTOA' AND F.CODE2 = DECODE(A.ACCOUNT_TYPE,NULL,B.ACCOUNT_TYPE, A.ACCOUNT_TYPE ) ) BUDGET_DEPT_NAME, NVL(TRIM(B.OVER_SHORT_FLAG),'N') AS OVER_SHORT_FLAG, TRIM(B.HS_NO) AS HS_NO, B.PRODUCT_CLOSE_FLAG AS PRODUCT_CLOSE_FLAG ,C.PROCESS_TYPE ,DECODE( C.PROCESS_TYPE,'1' , (SELECT DECODE(COUNT(*),0,'N','Y') FROM ICOMBYIT IT, ICOMCOD1 D, WMSSTCK W WHERE D.TYPE ='HUB' AND D.CODE = C.AGENT AND IT.BUYER_ITEM_NO = B.CMS_CATLG_ID AND IT.PRODUCT_CLOSE_FLAG ='N' AND W.STDCATLG_ID = IT.BUYER_ITEM_NO AND W.WAREHOUSE_CODE = D.TEXT1 ) , 'Y' ) AS STOCK_ITEM_FLAG , A.HI_DEPT_CODE , (SELECT TEXT2 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND CODE = A.HI_DEPT_CODE AND TYPE = 'U001' AND FLAG = 'Y') AS HI_DEPT_NAME , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND CODE = A.REF_PR_NO AND TYPE = 'M014' AND FLAG = 'Y') AS REF_PR_NAME , A.MG_CODE , A.MG_NOTE , DECODE((SELECT COUNT(*) FROM ICOMATCH WHERE DOC_NO = A.IMAGE_KEY), 0, '', A.IMAGE_KEY) AS IMAGE_KEY , (SELECT NVL(PLAN_AMT, 0) - NVL(RESULT_AMT, 0) - NVL(TEMP_AMT, 0) FROM ICOMBDGT WHERE BUYER = A.BUYER AND DEPT = A.BUDGET_DEPT AND ACCOUNT_TYPE = A.ACCOUNT_TYPE AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN FROM_DATE AND TO_DATE) AS BDGT_BAL_AMT , A.SEQ , CASE WHEN B.CATEGORY_NO IN ( SELECT DISTINCT STD_CATEG_ID FROM ( SELECT STD_CATEG_ID FROM ICOMBYCA A, ICOMCOD3 B WHERE A.COM_CODE=B.BUYER AND A.COM_CODE = ( SELECT DISTINCT BYCA_COMORG_CODE FROM ICOMCMPY WHERE (COM_CODE = #{st_buyer} OR BYCA_COMORG_CODE = #{st_buyer}) ) AND A.COM_CODE = B.TEXT1 AND B.TYPE = 'URCT2' AND B.CODE1 = #{st_user_id} AND B.FLAG = 'Y' AND SUBSTR(A.CATEG_SYS_CODE,1,8) = B.TEXT2 UNION ALL SELECT DISTINCT STD_CATEG_ID FROM ICOMBYCA A WHERE A.COM_CODE = ( SELECT DISTINCT BYCA_COMORG_CODE FROM ICOMCMPY WHERE (COM_CODE = #{st_buyer} OR BYCA_COMORG_CODE = #{st_buyer}) ) AND NOT EXISTS ( SELECT 1 FROM ICOMCOD3 B WHERE B.BUYER = A.COM_CODE AND B.TEXT1 = A.COM_CODE AND B.TEXT2 = SUBSTR(A.CATEG_SYS_CODE,1,8) AND B.TYPE = 'URCT2' AND B.FLAG = 'Y' ) ) ) THEN 'Y' ELSE 'N' END AS URCT2_YN FROM ICOMCART A, ICOMBYIT B, ICOMCQDT C WHERE B.BUYER = C.BUYER AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND A.BUYER = #{st_buyer} AND A.BYIT_COMORG_CODE = B.BUYER AND A.USER_ID = #{st_user_id}
AND C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ||A.SEQ IN
#{item}
AND C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ IN
#{item}
AND A.USE_FLAG = 'C' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG IN ('N','Y') ORDER BY 1,2,3 ) Y ) Z



