/*getShoppintCartClcsSelectSql1*/ SELECT XXX.* , ROWNUM RNO FROM ( SELECT YYY.* , COUNT(*) OVER() AS TOTNUM , ROWNUM RN FROM ( SELECT ROWNUM NO , Z.IMGFILE_NAME , Z.IMGFILE_DIR , Z.BUYER_ITEM_NO , Z.DESCRIPTION_LOC , Z.SPECIFICATION , Z.ORIGIN_NAME , Z.MAKER_NAME , Z.UNIT_MEASURE , Z.TARGET_PRICE , Z.CATEGORY_NO , DECODE(NVL(Z.AGENT, 'MULTI'), 'MULTI', '복수협력사입니다', '+', '복수협력사입니다', DECODE ( (SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE COM_CODE = #{st_buyer} ), 'N', '코리아e플랫폼(주)', Z.AGENT ) ) AGENT , Z.CART_QTY , Z.TOT_SUM , Z.STDCATEG_ID , Z.CONTRACT_NO , Z.CONTRACT_SEQ , Z.BYIT_COMORG_CODE , Z.REF_PR_NO , Z.AGENT_CODE , Z.BDGT_FLAG , Z.ACCOUNT_TYPE , Z.FIXED_PRICE_FLAG , DECODE ( (SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE COM_CODE = #{st_buyer} ), 'N', 'KRKORE0001', Z.AGENT_CODE ) AGENT3 , Z.ACCOUNT_NAME , Z.BUDGET_DEPT_CODE , Z.BUDGET_DEPT_NAME , Z.OVER_SHORT_FLAG , Z.HS_NO , Z.PRODUCT_CLOSE_FLAG , Z.PROCESS_TYPE , Z.STOCK_ITEM_FLAG , Z.REF_PR_NAME , Z.IMAGE_KEY , (SELECT TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'K005' AND COD.FLAG = 'Y' AND COD.CODE = Z.BUYER_ITEM_NO AND ROWNUM = 1 ) COWAY_NAMECARD , Z.BYIT_BDGT_FLAG , Z.CMS_CATEG_ID , Z.CATE_APPR , Z.BCODE , Z.ZCODE , Z.ZCODE_COUNT , Z.CART_SEQ , Z.MG_CODE , Z.MG_NOTE , Z.REQ_USER_NAME , Z.SMENGE , Z.LMENGE , Z.COWAY_BUDAM_PRICE , (Z.CART_QTY * Z.COWAY_BUDAM_PRICE) AS COWAY_BUDAM_AMT , Z.ZCODE_NM , (SELECT COBY.GONGJE FROM COWAY_BYIT COBY WHERE COBY.BCODE = Z.BCODE AND COBY.ZCODE = Z.ZCODE AND COBY.MATNR = Z.BUYER_ITEM_NO) AS GONGJE FROM (SELECT ROWNUM NUM , Y.IMGFILE_NAME , Y.IMGFILE_DIR , Y.BUYER_ITEM_NO , Y.DESCRIPTION_LOC , Y.SPECIFICATION , Y.ORIGIN_NAME , Y.MAKER_NAME , Y.UNIT_MEASURE , Y.TARGET_PRICE , Y.CATEGORY_NO , Y.AGENT , Y.CART_QTY , Y.TOT_SUM , Y.STDCATEG_ID , Y.CONTRACT_NO , Y.CONTRACT_SEQ , Y.BYIT_COMORG_CODE , Y.REF_PR_NO , Y.AGENT_CODE , Y.BDGT_FLAG , NVL(Y.ACCOUNT_TYPE, GETCOWAYBGACTIFNO('BGACT', Y.BUYER, Y.USER_ID, Y.BUDGET_DEPT_CODE)) ACCOUNT_TYPE , Y.FIXED_PRICE_FLAG , GETCOWAYBGACT_NMIFNO('BGACT', Y.BUYER, Y.USER_ID, NVL(Y.ACCOUNT_TYPE, GETCOWAYBGACTIFNO('BGACT', Y.BUYER, Y.USER_ID, Y.BUDGET_DEPT_CODE))) ACCOUNT_NAME , Y.BUDGET_DEPT_CODE , GETCOWAYBGACT_NMIFNO('BGORG', Y.BUYER, Y.USER_ID, Y.BUDGET_DEPT_CODE) BUDGET_DEPT_NAME , Y.OVER_SHORT_FLAG , Y.HS_NO , Y.PRODUCT_CLOSE_FLAG , Y.PROCESS_TYPE , Y.STOCK_ITEM_FLAG , Y.REF_PR_NAME , Y.IMAGE_KEY , Y.BYIT_BDGT_FLAG , Y.CMS_CATEG_ID , Y.CATE_APPR , CASE WHEN Y.MG_NOTE IS NOT NULL THEN F_SPLIT(Y.MG_NOTE, CHR(38), 2) WHEN Y.ZCODE_COUNT = 1 THEN Y.BCODE ELSE '' END BCODE , CASE WHEN Y.MG_NOTE IS NOT NULL THEN F_SPLIT(Y.MG_NOTE, CHR(38), 1) WHEN Y.ZCODE_COUNT = 1 THEN Y.ZCODE ELSE '' END ZCODE , Y.ZCODE_COUNT , Y.CART_SEQ , Y.MG_CODE , Y.MG_NOTE , Y.REQ_USER_NAME , Y.SMENGE , Y.LMENGE , F_COWAY_BUDAM_AMT(Y.BUYER_ITEM_NO, CASE WHEN Y.MG_NOTE IS NOT NULL THEN F_SPLIT(Y.MG_NOTE, CHR(38), 1) WHEN Y.ZCODE_COUNT >= 1 THEN Y.ZCODE ELSE '' END, DECODE(Y.BUYER, 'KRCOWA0002', #{st_ji_gubun }, 'KRCOWA0003', #{st_sin_gubun }, 'KRCOWA0007', #{st_ji_gubun }, 'KRCOWA0008', #{st_ji_gubun }) ) AS COWAY_BUDAM_PRICE , (SELECT '('||DECODE(G.TEXT4,'1','수','2','운','X')||')'||K.TEXT1 FROM ICOMCOD2 K , ICOMCOD2 G WHERE K.COMPANY_CODE = Y.BUYER AND K.TYPE = 'Z019' AND K.FLAG = 'Y' AND K.CODE = ( CASE WHEN Y.MG_NOTE IS NOT NULL THEN F_SPLIT(Y.MG_NOTE, CHR(38), 1) WHEN Y.ZCODE_COUNT = 1 THEN Y.ZCODE ELSE '' END ) AND G.TYPE = 'Z018' AND G.COMPANY_CODE = K.COMPANY_CODE AND G.TEXT1 = K.CODE AND G.TEXT2 = Y.BCODE ) ZCODE_NM FROM (SELECT DECODE(TRIM(B.IMGFILE_NAME), NULL, (SELECT IMG_NAME FROM CMSIMGES WHERE IMG_NO = D.IMG_NO ), B.IMGFILE_NAME) AS IMGFILE_NAME , DECODE(TRIM(B.IMGFILE_DIR), NULL, (SELECT IMG_DIR FROM CMSIMGES WHERE IMG_NO = D.IMG_NO ), B.IMGFILE_DIR) AS IMGFILE_DIR , C.BUYER_ITEM_NO BUYER_ITEM_NO , C.DESCRIPTION DESCRIPTION_LOC , C.SPECIFICATION , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = C.ORIGIN_CODE ) ORIGIN_NAME , C.MAKER_NAME , C.UNIT_MEASURE , DECODE(B.FIXED_PRICE_FLAG, 'N', NVL(A.UNIT_PRICE, 0), NVL(C.TARGET_PRICE, 0)) TARGET_PRICE , B.CATEGORY_NO , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE C.AGENT = COM_CODE ) AS AGENT , DECODE(A.CART_QTY, '0', '1', NVL(A.CART_QTY, 1)) CART_QTY , (DECODE(A.CART_QTY, '0', '1', NVL(A.CART_QTY, 1)) * DECODE(B.FIXED_PRICE_FLAG, 'N', NVL(A.UNIT_PRICE, 0), NVL(C.TARGET_PRICE, 0)) ) TOT_SUM , B.STDCATEG_ID , C.CONTRACT_NO , C.CONTRACT_SEQ , A.BYIT_COMORG_CODE , A.REF_PR_NO , C.AGENT AS AGENT_CODE , (SELECT Z.FLAG FROM ICOMCOD2 Z WHERE Z.TYPE = 'Z014' AND Z.COMPANY_CODE = A.BUYER AND Z.CODE = B.ACCOUNT_TYPE ) BDGT_FLAG , B.FIXED_PRICE_FLAG FIXED_PRICE_FLAG , NVL(A.BUDGET_DEPT, GETCOWAYBGACTIFNO('BGORG', A.BUYER, A.USER_ID, '')) BUDGET_DEPT_CODE , A.ACCOUNT_TYPE , NVL(TRIM(B.OVER_SHORT_FLAG), 'N') AS OVER_SHORT_FLAG , TRIM(B.HS_NO) AS HS_NO , B.PRODUCT_CLOSE_FLAG AS PRODUCT_CLOSE_FLAG , C.PROCESS_TYPE ,DECODE(C.PROCESS_TYPE, '1', (SELECT DECODE(COUNT(*),0,'N','Y') FROM ICOMBYIT IT, ICOMCOD1 D, WMSSTCK W WHERE D.TYPE ='HUB' AND D.CODE = C.AGENT AND IT.BUYER_ITEM_NO = B.CMS_CATLG_ID AND IT.PRODUCT_CLOSE_FLAG ='N' AND W.STDCATLG_ID = IT.BUYER_ITEM_NO AND W.WAREHOUSE_CODE = D.TEXT1 ) , 'Y') AS STOCK_ITEM_FLAG , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND CODE = A.REF_PR_NO AND TYPE = 'M014' AND FLAG = 'Y' ) AS REF_PR_NAME , A.IMAGE_KEY , A.BUYER , A.USER_ID , ( CASE WHEN E.BUDGET_FLAG = 'Y' AND B.ACCOUNT_TYPE = 'M' THEN 'Y' ELSE 'N' END ) AS BYIT_BDGT_FLAG , B.CMS_CATEG_ID , (SELECT COUNT( * ) FROM ICOMCOD3 CT WHERE CT.BUYER = A.BUYER AND CT.CODE1 = B.CATEGORY_NO AND CT.TYPE = 'CATE' AND CT.FLAG = 'Y' ) AS CATE_APPR , F.BCODE , F.ZCODE , NVL(F.ROW_NUM, 0) AS ZCODE_COUNT , A.SEQ AS CART_SEQ , A.MG_CODE , A.MG_NOTE , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.REF_PR_NO ) AS REQ_USER_NAME , F.SMENGE , F.LMENGE FROM ICOMCART A , ICOMBYIT B , ICOMCQDT C , CMSCATLG D , ICOMCMPY E , (SELECT MATNR, MAX(BCODE) AS BCODE, MAX(ZCODE) AS ZCODE, MAX(CLS) AS CLS , COUNT(DISTINCT ZCODE||CASE WHEN CLS = 'CW' THEN GONGJE ELSE '1'END ) AS ROW_NUM , MAX(SMENGE) AS SMENGE, MAX(LMENGE) AS LMENGE FROM COWAY_BYIT WHERE 1=1 AND CLS=DECODE(#{st_buyer}, 'KRCOWA0002','CL','KRCOWA0003','CS','KRCOWA0007','CH','KRCOWA0008','CW')
AND GONGJE IN (SELECT DECODE(ROLE_GBN,'W','2','S','1') ROLE_GBN FROM( SELECT CODE ,TEXT2 AS ROLE_GBN FROM ICOMCOD2 COD2 WHERE TYPE = 'C007' AND COMPANY_CODE= #{st_buyer} AND COD2.CODE = #{st_user_id} UNION ALL SELECT CODE ,TEXT3 AS ROLE_GBN FROM ICOMCOD2 COD2 WHERE TYPE = 'C007' AND COMPANY_CODE= #{st_buyer} AND COD2.CODE = #{st_user_id} ) X WHERE X.ROLE_GBN IS NOT NULL )
GROUP BY MATNR ) F WHERE B.BUYER = C.BUYER AND A.BUYER = E.COM_CODE AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND A.BUYER = #{st_buyer} AND A.BYIT_COMORG_CODE = B.BUYER AND A.USER_ID = #{st_user_id} AND B.CMS_CATLG_ID = D.CMS_CATLG_ID(+) AND D.STD_FLAG(+) = 'Y' AND A.USE_FLAG = 'C' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG IN ('N', 'Y') AND A.BUYER_ITEM_NO = F.MATNR(+)
AND A.VERIF_NUM = #{st_verif_num}
ORDER BY A.CREATE_DATE, A.SEQ, A.BUYER_ITEM_NO
ORDER BY A.BUYER_ITEM_NO
ORDER BY A.REF_PR_NO, A.BUYER_ITEM_NO
) Y ) Z
) YYY ) XXX WHERE XXX.RN BETWEEN #{startrow} AND #{endrow}

/*getBuyerShoppingCartClcsOrderListConfirm1*/ SELECT NUM NO , Z.IMGFILE_NAME , Z.IMGFILE_DIR , Z.BUYER_ITEM_NO , Z.DESCRIPTION_LOC , Z.SPECIFICATION , Z.ORIGIN_NAME , Z.MAKER_NAME , Z.UNIT_MEASURE , Z.TARGET_PRICE , Z.CATEGORY_NO , DECODE(NVL(Z.AGENT, 'MULTI'), 'MULTI', '복수협력사입니다', '+', '복수협력사입니다', DECODE ( (SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE COM_CODE = #{st_buyer} ), 'N', '코리아e플랫폼(주)', Z.AGENT ) ) AGENT , Z.CART_QTY , Z.TOT_SUM , Z.STDCATEG_ID , Z.CONTRACT_NO , Z.CONTRACT_SEQ , Z.BYIT_COMORG_CODE , Z.REF_PR_NO , Z.AGENT_CODE , Z.BDGT_FLAG , Z.ACCOUNT_TYPE , Z.FIXED_PRICE_FLAG , DECODE(NVL(Z.AGENT, 'MULTI'), 'MULTI', 'MULTI_AGENT', DECODE ( (SELECT MAX(AGENT_OPEN_FLAG) FROM ICOMCMPY WHERE COM_CODE = #{st_buyer} ), 'N', 'KRKORE0001', Z.AGENT_CODE ) ) AGENT3 , Z.ACCOUNT_NAME , Z.BUDGET_DEPT_CODE , Z.BUDGET_DEPT_NAME , Z.OVER_SHORT_FLAG , Z.HS_NO , Z.PRODUCT_CLOSE_FLAG , Z.PROCESS_TYPE , Z.STOCK_ITEM_FLAG , Z.REF_PR_NAME , Z.IMAGE_KEY , (SELECT TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE = 'K005' AND COD.FLAG = 'Y' AND COD.CODE = Z.BUYER_ITEM_NO AND ROWNUM = 1 ) COWAY_NAMECARD , Z.BYIT_BDGT_FLAG , Z.CMS_CATEG_ID , Z.CATE_APPR , Z.BCODE , Z.ZCODE , Z.ZCODE_COUNT , Z.CART_SEQ , Z.MG_CODE , Z.MG_NOTE , Z.REQ_USER_NAME , Z.SMENGE , Z.LMENGE , Z.COWAY_BUDAM_PRICE , (Z.CART_QTY * Z.COWAY_BUDAM_PRICE) AS COWAY_BUDAM_AMT , Z.ZCODE_NM FROM (SELECT ROWNUM NUM , Y.IMGFILE_NAME , Y.IMGFILE_DIR , Y.BUYER_ITEM_NO , Y.DESCRIPTION_LOC , Y.SPECIFICATION , Y.ORIGIN_NAME , Y.MAKER_NAME , Y.UNIT_MEASURE , Y.TARGET_PRICE , Y.CATEGORY_NO , Y.AGENT , Y.CART_QTY , Y.TOT_SUM , Y.STDCATEG_ID , Y.CONTRACT_NO , Y.CONTRACT_SEQ , Y.BYIT_COMORG_CODE , Y.REF_PR_NO , Y.AGENT_CODE , Y.BDGT_FLAG , Y.OVER_SHORT_FLAG , NVL(Y.ACCOUNT_TYPE, GETCOWAYBGACTIFNO('BGACT', Y.BUYER, Y.USER_ID, Y.BUDGET_DEPT_CODE)) ACCOUNT_TYPE , Y.FIXED_PRICE_FLAG , GETCOWAYBGACT_NMIFNO('BGACT', Y.BUYER, Y.USER_ID, NVL(Y.ACCOUNT_TYPE, GETCOWAYBGACTIFNO('BGACT', Y.BUYER, Y.USER_ID, Y.BUDGET_DEPT_CODE))) ACCOUNT_NAME , Y.BUDGET_DEPT_CODE , GETCOWAYBGACT_NMIFNO('BGORG', Y.BUYER, Y.USER_ID, Y.BUDGET_DEPT_CODE) BUDGET_DEPT_NAME , Y.HS_NO , Y.PRODUCT_CLOSE_FLAG , Y.PROCESS_TYPE , Y.STOCK_ITEM_FLAG , Y.REF_PR_NAME , Y.IMAGE_KEY , Y.BYIT_BDGT_FLAG , Y.CMS_CATEG_ID , Y.CATE_APPR , CASE WHEN Y.MG_NOTE IS NOT NULL THEN F_SPLIT(Y.MG_NOTE, CHR(38), 2) WHEN Y.ZCODE_COUNT = 1 THEN Y.BCODE ELSE '' END BCODE , CASE WHEN Y.MG_NOTE IS NOT NULL THEN F_SPLIT(Y.MG_NOTE, CHR(38), 1) WHEN Y.ZCODE_COUNT = 1 THEN Y.ZCODE ELSE '' END ZCODE , Y.ZCODE_COUNT , Y.CART_SEQ , Y.MG_CODE , Y.MG_NOTE , Y.REQ_USER_NAME , Y.SMENGE , Y.LMENGE , F_COWAY_BUDAM_AMT(Y.BUYER_ITEM_NO, CASE WHEN Y.MG_NOTE IS NOT NULL THEN F_SPLIT(Y.MG_NOTE, CHR(38), 1) WHEN Y.ZCODE_COUNT >= 1 THEN Y.ZCODE ELSE '' END, DECODE(Y.BUYER, 'KRCOWA0002', #{ji_gubun }, 'KRCOWA0003', #{sin_gubun }, 'KRCOWA0007', #{ji_gubun }, 'KRCOWA0008', #{ji_gubun }) ) AS COWAY_BUDAM_PRICE , (SELECT K.TEXT1 FROM ICOMCOD2 K WHERE K.COMPANY_CODE = Y.BUYER AND K.FLAG = 'Y' AND K.CODE = ( CASE WHEN Y.MG_NOTE IS NOT NULL THEN F_SPLIT(Y.MG_NOTE, CHR(38), 1) ELSE Y.ZCODE END ) ) ZCODE_NM FROM (SELECT TRIM(DECODE(SUBSTR(B.STDCATLG_ID, 0, 1), 'M', (SELECT IMG_NAME FROM XPROIMGE WHERE IMG_NO = (SELECT DISTINCT IMG_NO FROM ITEMMAST WHERE STDCATLG_ID = B.STDCATLG_ID ) AND RANKING = 1 ), B.IMGFILE_NAME)) AS IMGFILE_NAME , TRIM(DECODE(SUBSTR(B.STDCATLG_ID, 0, 1), 'M', (SELECT IMG_DIR FROM XPROIMGE WHERE IMG_NO = (SELECT DISTINCT IMG_NO FROM ITEMMAST WHERE STDCATLG_ID = B.STDCATLG_ID ) AND RANKING = 1 ), B.IMGFILE_DIR)) AS IMGFILE_DIR , C.BUYER_ITEM_NO BUYER_ITEM_NO , C.DESCRIPTION DESCRIPTION_LOC , C.SPECIFICATION , (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = C.ORIGIN_CODE ) ORIGIN_NAME , C.MAKER_NAME , C.UNIT_MEASURE , DECODE(B.FIXED_PRICE_FLAG, 'N', NVL(A.UNIT_PRICE, 0), NVL(C.TARGET_PRICE, 0)) TARGET_PRICE , B.CATEGORY_NO , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE C.AGENT = COM_CODE ) AS AGENT , DECODE(A.CART_QTY, '0', '1', NVL(A.CART_QTY, 1)) CART_QTY , (DECODE(A.CART_QTY, '0', '1', NVL(A.CART_QTY, 1)) * DECODE(B.FIXED_PRICE_FLAG, 'N', NVL(A.UNIT_PRICE, 0), NVL(C.TARGET_PRICE, 0)) ) TOT_SUM , B.STDCATEG_ID , C.CONTRACT_NO , C.CONTRACT_SEQ , A.BYIT_COMORG_CODE , A.REF_PR_NO , C.AGENT AS AGENT_CODE , (SELECT Z.FLAG FROM ICOMCOD2 Z WHERE Z.TYPE = 'Z014' AND Z.COMPANY_CODE = A.BUYER AND Z.CODE = B.ACCOUNT_TYPE ) BDGT_FLAG , B.FIXED_PRICE_FLAG FIXED_PRICE_FLAG , NVL(A.BUDGET_DEPT, GETCOWAYBGACTIFNO('BGORG', A.BUYER, A.USER_ID, '')) BUDGET_DEPT_CODE , A.ACCOUNT_TYPE , NVL(TRIM(B.OVER_SHORT_FLAG), 'N') AS OVER_SHORT_FLAG , TRIM(B.HS_NO) AS HS_NO , B.PRODUCT_CLOSE_FLAG AS PRODUCT_CLOSE_FLAG , C.PROCESS_TYPE , DECODE( C.PROCESS_TYPE, '1', (SELECT DECODE(COUNT( * ), 0, 'N', 'Y') FROM ICOMBYIT IT, ICOMCOD1 D, WMSSTCK W WHERE D.TYPE ='HUB' AND D.CODE = C.AGENT AND IT.BUYER_ITEM_NO = B.CMS_CATLG_ID AND IT.PRODUCT_CLOSE_FLAG ='N' AND W.STDCATLG_ID = IT.BUYER_ITEM_NO AND W.WAREHOUSE_CODE = D.TEXT1 ) , 'Y' ) AS STOCK_ITEM_FLAG , (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = A.BUYER AND CODE = A.REF_PR_NO AND TYPE = 'M014' AND FLAG = 'Y' ) AS REF_PR_NAME , A.IMAGE_KEY , A.BUYER , A.USER_ID , ( CASE WHEN E.BUDGET_FLAG = 'Y' AND B.ACCOUNT_TYPE = 'M' THEN 'Y' ELSE 'N' END ) AS BYIT_BDGT_FLAG , B.CMS_CATEG_ID , (SELECT COUNT( * ) FROM ICOMCOD3 CT WHERE CT.BUYER = A.BUYER AND CT.CODE1 = B.CATEGORY_NO AND CT.TYPE = 'CATE' AND CT.FLAG = 'Y' ) AS CATE_APPR , F.BCODE , F.ZCODE , NVL(F.ROW_NUM, 0) AS ZCODE_COUNT , A.SEQ AS CART_SEQ , A.MG_CODE , A.MG_NOTE , (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.REF_PR_NO ) AS REQ_USER_NAME , F.SMENGE , F.LMENGE FROM ICOMCART A , ICOMBYIT B , ICOMCQDT C , ICOMCMPY E , (SELECT MATNR, MAX(BCODE) AS BCODE, MAX(ZCODE) AS ZCODE, MAX(CLS) AS CLS, COUNT(DISTINCT ZCODE) AS ROW_NUM , MAX(SMENGE) AS SMENGE, MAX(LMENGE) AS LMENGE FROM COWAY_BYIT WHERE 1=1 AND CLS=DECODE(#{st_buyer}, 'KRCOWA0002','CL','KRCOWA0003','CS','KRCOWA0007','CH','KRCOWA0008','CW') GROUP BY MATNR ) F WHERE B.BUYER = C.BUYER AND A.BUYER = E.COM_CODE AND A.BUYER_ITEM_NO = B.BUYER_ITEM_NO AND A.BUYER_ITEM_NO = C.BUYER_ITEM_NO AND A.CONTRACT_NO = C.CONTRACT_NO AND A.CONTRACT_SEQ = C.CONTRACT_SEQ AND A.BUYER = #{st_buyer} AND A.BYIT_COMORG_CODE = B.BUYER AND A.USER_ID = #{st_user_id}
AND C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ||A.SEQ IN
#{item}
AND C.BUYER_ITEM_NO||C.CONTRACT_NO||C.CONTRACT_SEQ IN
#{item}
AND A.USE_FLAG = 'C' AND B.STATUS <> 'D' AND C.STATUS <> 'D' AND B.PRODUCT_CLOSE_FLAG IN ('N','Y') AND A.BUYER_ITEM_NO = F.MATNR(+) ORDER BY 1,2,3 ) Y ) Z

